  "ip_address" TEXT,
  "user_agent" TEXT,
  "details" TEXT DEFAULT '{}' NOT NULL,
  "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL
);

CREATE TABLE IF NOT EXISTS "security_rate_limits" (
  "key" TEXT NOT NULL,
  "attempts" INTEGER DEFAULT 0 NOT NULL,
  "expires_at" TEXT NOT NULL,
  PRIMARY KEY ("key")
);

CREATE TABLE IF NOT EXISTS "skills" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  "name" TEXT NOT NULL,
  "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,
  UNIQUE ("name")
);

CREATE TABLE IF NOT EXISTS "staff_activity_logs" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  "staff_user_id" INTEGER,
  "action" TEXT NOT NULL,
  "resource_type" TEXT,
  "resource_id" TEXT,
  "ip_address" TEXT,
  "details" TEXT DEFAULT '{}' NOT NULL,
  "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL
);

CREATE TABLE IF NOT EXISTS "support_messages" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  "ticket_id" INTEGER NOT NULL,
  "from_user" INTEGER DEFAULT 1 NOT NULL,
  "body" TEXT NOT NULL,
  "attachment_url" TEXT,
  "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,
  FOREIGN KEY ("ticket_id") REFERENCES "support_tickets" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "support_tickets" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  "user_id" INTEGER NOT NULL,
  "subject" TEXT NOT NULL,
  "category" TEXT DEFAULT 'general' NOT NULL,
  "status" TEXT DEFAULT 'open' NOT NULL,
  "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,
  "updated_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,
  FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "user_goals" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  "user_id" INTEGER NOT NULL,
  "title" TEXT NOT NULL,
  "metric" TEXT,
  "target" REAL DEFAULT 1 NOT NULL,
  "current" REAL DEFAULT 0 NOT NULL,
  "due_date" TEXT,
  "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,
  FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "user_settings" (
  "user_id" INTEGER NOT NULL,
  "data" TEXT DEFAULT '{}' NOT NULL,
  "updated_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,
  PRIMARY KEY ("user_id"),
  FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "user_tasks" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  "user_id" INTEGER NOT NULL,
  "title" TEXT NOT NULL,
  "description" TEXT,
  "due_date" TEXT,
  "priority" TEXT DEFAULT 'medium' NOT NULL,
  "category" TEXT,
  "status" TEXT DEFAULT 'todo' NOT NULL,
  "assignee_id" INTEGER,
  "completed_at" TEXT,
  "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,
  FOREIGN KEY ("assignee_id") REFERENCES "users" ("id") ON DELETE SET NULL,
  FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "users" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  "username" TEXT NOT NULL,
  "email" TEXT NOT NULL,
  "password_hash" TEXT NOT NULL,
  "name" TEXT,
  "role" TEXT DEFAULT 'user' NOT NULL,
  "status" TEXT DEFAULT 'active' NOT NULL,
  "failed_login_attempts" INTEGER DEFAULT 0 NOT NULL,
  "locked_until" TEXT,
  "last_login_at" TEXT,
  "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,
  "updated_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,
  "account_type" TEXT DEFAULT 'individual' NOT NULL,
  "email_verified_at" TEXT,
  "verified" INTEGER DEFAULT 0 NOT NULL,
  "verified_badge" TEXT,
  UNIQUE ("email"),
  UNIQUE ("username"),
  CHECK (account_type IN ('individual', 'company')),
  CHECK (role IN ('user', 'staff', 'admin')),
  CHECK (status IN ('active', 'suspended', 'deactivated'))
);

CREATE INDEX IF NOT EXISTS "blocks_blocked_idx" ON "blocks" ("blocked_id");
CREATE INDEX IF NOT EXISTS "comments_post_created_idx" ON "comments" ("post_id", "created_at");
CREATE INDEX IF NOT EXISTS "comments_user_idx" ON "comments" ("user_id", "created_at");
CREATE INDEX IF NOT EXISTS "company_members_user_idx" ON "company_members" ("user_id", "created_at");
CREATE INDEX IF NOT EXISTS "connections_pending_recipient_idx" ON "connections" ("recipient_id", "status");
CREATE INDEX IF NOT EXISTS "connections_recipient_idx" ON "connections" ("recipient_id", "status");
CREATE INDEX IF NOT EXISTS "connections_requester_idx" ON "connections" ("requester_id", "status");
CREATE INDEX IF NOT EXISTS "conversation_members_user_idx" ON "conversation_members" ("user_id", "joined_at");
CREATE INDEX IF NOT EXISTS "follows_following_idx" ON "follows" ("following_id");
CREATE INDEX IF NOT EXISTS "idx_audit_logs_actor" ON "audit_logs" ("actor_user_id");
CREATE INDEX IF NOT EXISTS "idx_audit_logs_created" ON "audit_logs" ("created_at");
CREATE INDEX IF NOT EXISTS "idx_audit_logs_target" ON "audit_logs" ("target_user_id");
CREATE INDEX IF NOT EXISTS "idx_auth_sessions_active" ON "auth_sessions" ("user_id", "expires_at") WHERE (revoked_at IS NULL);
CREATE INDEX IF NOT EXISTS "idx_auth_sessions_user" ON "auth_sessions" ("user_id");
CREATE INDEX IF NOT EXISTS "idx_email_verification_live" ON "email_verification_tokens" ("user_id") WHERE (used_at IS NULL);
CREATE INDEX IF NOT EXISTS "idx_email_verification_user" ON "email_verification_tokens" ("user_id");
CREATE INDEX IF NOT EXISTS "idx_password_reset_live" ON "password_reset_tokens" ("user_id") WHERE (used_at IS NULL);
CREATE INDEX IF NOT EXISTS "idx_password_reset_user" ON "password_reset_tokens" ("user_id");
CREATE INDEX IF NOT EXISTS "idx_security_events_created" ON "security_events" ("created_at");
CREATE INDEX IF NOT EXISTS "idx_security_events_type" ON "security_events" ("event_type");
CREATE INDEX IF NOT EXISTS "idx_security_events_user" ON "security_events" ("user_id");
CREATE INDEX IF NOT EXISTS "idx_security_rate_limits_expiry" ON "security_rate_limits" ("expires_at");
CREATE INDEX IF NOT EXISTS "idx_staff_activity_created" ON "staff_activity_logs" ("created_at");
CREATE INDEX IF NOT EXISTS "job_applications_applicant_idx" ON "job_applications" ("applicant_id", "created_at");
CREATE INDEX IF NOT EXISTS "job_applications_job_idx" ON "job_applications" ("job_id", "created_at");
CREATE INDEX IF NOT EXISTS "job_listings_company_idx" ON "job_listings" ("company_id", "created_at");
CREATE INDEX IF NOT EXISTS "job_listings_status_idx" ON "job_listings" ("status", "created_at");
CREATE INDEX IF NOT EXISTS "marketplace_seller_idx" ON "marketplace_listings" ("seller_id", "created_at");
CREATE INDEX IF NOT EXISTS "marketplace_status_idx" ON "marketplace_listings" ("status", "created_at");
CREATE INDEX IF NOT EXISTS "messages_conversation_idx" ON "messages" ("conversation_id", "created_at");
CREATE INDEX IF NOT EXISTS "messages_sender_idx" ON "messages" ("sender_id", "created_at");
CREATE INDEX IF NOT EXISTS "notifications_unread_idx" ON "notifications" ("user_id", "read_at", "created_at");
CREATE INDEX IF NOT EXISTS "notifications_user_idx" ON "notifications" ("user_id", "created_at");
CREATE INDEX IF NOT EXISTS "posts_created_idx" ON "posts" ("created_at");
CREATE INDEX IF NOT EXISTS "posts_user_created_idx" ON "posts" ("user_id", "created_at");
CREATE INDEX IF NOT EXISTS "posts_visibility_created_idx" ON "posts" ("visibility", "created_at");
CREATE INDEX IF NOT EXISTS "profiles_first_name_idx" ON "profiles" (lower(first_name));
CREATE INDEX IF NOT EXISTS "profiles_last_name_idx" ON "profiles" (lower(last_name));
CREATE INDEX IF NOT EXISTS "profiles_location_idx" ON "profiles" ("location");
CREATE INDEX IF NOT EXISTS "profiles_onboarding_done_idx" ON "profiles" ("onboarding_done");
CREATE INDEX IF NOT EXISTS "profiles_username_idx" ON "profiles" (lower(username));
CREATE INDEX IF NOT EXISTS "reviews_subject_idx" ON "reviews" ("subject_type", "subject_id", "created_at");
CREATE INDEX IF NOT EXISTS "saved_items_user_idx" ON "saved_items" ("user_id", "saved_at");
CREATE INDEX IF NOT EXISTS "saved_posts_user_idx" ON "saved_posts" ("user_id", "created_at");
CREATE INDEX IF NOT EXISTS "search_history_user_idx" ON "search_history" ("user_id", "created_at");
CREATE INDEX IF NOT EXISTS "user_tasks_user_idx" ON "user_tasks" ("user_id", "status", "due_date");
CREATE INDEX IF NOT EXISTS "users_account_type_idx" ON "users" ("account_type");
CREATE INDEX IF NOT EXISTS "users_email_idx" ON "users" (lower(email));
CREATE INDEX IF NOT EXISTS "users_username_idx" ON "users" (lower(username));

CREATE VIEW IF NOT EXISTS "conn_edges" AS SELECT connections.requester_id AS a,
    connections.recipient_id AS b
   FROM connections
  WHERE ((connections.status) = 'accepted')
UNION ALL
 SELECT connections.recipient_id AS a,
    connections.requester_id AS b
   FROM connections
  WHERE ((connections.status) = 'accepted');
